def bento_panel(label, h2, inner, sub="", cls="", sec_id=""):
    sub_html = f'<p class="bento-sub">{esc(sub)}</p>' if sub else ""
    id_attr = f' id="{sec_id}"' if sec_id else ""
    return f"""
<section class="home-bento {cls}"{id_attr}>
  <div class="container">
    <div class="bento-panel">
      <div class="bento-head">
        <span class="bento-label">{esc(label)}</span>
        <h2>{esc(h2)}</h2>
        {sub_html}
      </div>
      {inner}
    </div>
  </div>
</section>
"""

def prose(paragraphs):
    return '<div class="bento-prose">' + "".join(f"<p>{esc(p)}</p>" for p in paragraphs) + "</div>"

def info_cards(items):
    """items: (иконка, заголовок, текст, [ссылка, подпись])"""
    cards = []
    for it in items:
        ic, title, text = it[:3]
        link = f'<a class="info-card-link" href="{it[3]}">{esc(it[4])} {icon("chevron", 15)}</a>' if len(it) > 3 else ""
        cards.append(f'<div class="bento-card info-card"><div class="why-icon">{gicon(ic, 28)}</div><h3>{esc(title)}</h3><p>{esc(text)}</p>{link}</div>')
    cols = " info-grid-2" if len(cards) % 3 and len(cards) % 2 == 0 else ""
    return f'<div class="bento-grid info-grid{cols}">{"".join(cards)}</div>'

