ARTICLE_BY_RELATED = {}
for _a in ARTICLES:
    ARTICLE_BY_RELATED.setdefault(_a["related"], []).append(_a)

ARTICLE_ICONS = {"divana": "sofa", "zapaha-koshki": "nodrop", "zapaha-mochi": "bed"}

def article_cards(items):
    return info_cards([(ARTICLE_ICONS.get(a["related"], "spark"), a["nav"], a["card"], a["filename"], "Читать статью") for a in items])

def articles_panel(slug):
    """Блок «Полезные статьи» на странице услуги."""
    items = ARTICLE_BY_RELATED.get(slug)
    if not items:
        return ""
    return bento_panel("Статьи", "Полезно почитать", article_cards(items))

def render_article_body(blocks):
    out, toc, n = [], [], 0
    for kind, val in blocks:
        if kind == "h2":
            n += 1
            toc.append(f'<li><a href="#r{n}">{esc(val)}</a></li>')
            out.append(f'<h2 id="r{n}">{esc(val)}</h2>')
        elif kind == "p":
            out.append(f"<p>{esc(val)}</p>")
        elif kind in ("ul", "ol"):
            out.append(f"<{kind}>" + "".join(f"<li>{esc(x)}</li>" for x in val) + f"</{kind}>")
        elif kind == "note":
            out.append(f'<div class="article-note">{gicon("spark", 28)}<p>{esc(val)}</p></div>')
    return "".join(out), "".join(toc)

def article_schema(a):
    return {
        "@context": "https://schema.org", "@type": "Article",
        "headline": a["h1"], "description": a["description"],
        "mainEntityOfPage": url(a["filename"]), "inLanguage": "ru",
        "image": url("assets/img/og-image.jpg"),
        "datePublished": "2026-11-10", "dateModified": date.today().isoformat(),
        "author": {"@type": "Organization", "name": SITE["name"]},
        "publisher": {"@type": "Organization", "name": SITE["name"], "logo": {"@type": "ImageObject", "url": url("assets/img/logo.svg")}},
    }

def render_article(a):
    path = a["filename"]
    bc = [("Главная", "index.html"), ("Статьи", "stati.html"), (a["nav"], None)]
    s = SERVICE_BY_SLUG[a["related"]]
    body_html, toc = render_article_body(a["body"])
    service_card_html = f"""<div class="bento-card article-cta">
        <div class="why-icon">{gicon(ARTICLE_ICONS.get(a["related"], "spark"), 28)}</div>
        <h3>{esc(s["nav"])} от {esc(s["price_from"])} ₽</h3>
        <p>Приедем в день обращения, цену назовём до начала работ.</p>
        <a class="btn btn-primary btn-block" href="#zayavka">Оставить заявку</a>
        <a class="info-card-link" href="{service_filename(s["slug"])}">Подробнее об услуге {icon("chevron", 15)}</a>
      </div>"""
    inner = f"""<div class="article-layout">
      <aside class="article-aside">
        <div class="bento-card article-toc"><h3>Содержание</h3><ol>{toc}</ol></div>
        {service_card_html}
      </aside>
      <article class="article-body">{body_html}</article>
    </div>"""
    others = [x for x in ARTICLES if x is not a]
    sections = [
        bento_panel(f"Статья · {a['minutes']} мин чтения", "Разбираемся по порядку", inner, cls="home-article"),
        bento_panel("Вопросы и ответы", "Коротко о главном", faq_block(a["faq"]), cls="home-faq"),
        bento_panel("Статьи", "Читайте также", article_cards(others)),
    ]
    return simple_page(path, a["title"], a["description"],
        dict(slug=a["photo"], h1=a["h1"], lead=a["lead"], eyebrow="Полезные статьи"),
        sections, bc, [article_schema(a), faq_schema(a["faq"])])

def render_stati():
    path = "stati.html"
    bc = [("Главная", "index.html"), ("Статьи", None)]
    return simple_page(path,
        f"Полезные статьи о чистке мебели и выведении запахов | {SITE['short_name']}",
        "Советы мастеров химчистки: как почистить диван дома, как убрать запах кошачьей мочи и мочи с дивана и матраса.",
        dict(slug="divana", h1="Полезные статьи", lead="Советы мастеров химчистки: что можно сделать самому и когда лучше вызвать специалиста.", eyebrow="Полезные статьи"),
        [bento_panel("Статьи", "Все статьи", article_cards(ARTICLES))], bc)

