def main():
    os.makedirs(OUT, exist_ok=True)
    os.makedirs(os.path.join(OUT, "assets", "css"), exist_ok=True)
    os.makedirs(os.path.join(OUT, "assets", "js"), exist_ok=True)

    # Удаляем ранее сгенерированные html-страницы (на случай переименования слагов),
    # ассеты в assets/ не трогаем.
    for stale in glob.glob(os.path.join(OUT, "*.html")):
        os.remove(stale)

    all_paths = []

    def write(path, content):
        content = clean_links(typograf(content))
        with open(os.path.join(OUT, path), "w", encoding="utf-8") as f:
            f.write(content)
        all_paths.append(path)
        print_done(path)

    print("Генерация страниц услуг...")
    for s in SERVICES:
        p, c = render_service_page(s)
        write(p, c)

    print("Генерация основных страниц...")
    for renderer in (render_index, render_uslugi, render_onas, render_ceny, render_kontakty, render_privacy, render_soglasie):
        p, c = renderer()
        write(p, c)

    print("Генерация гео-страниц...")
    for g in GEO_PAGES:
        p, c = render_service_page(g)
        write(p, c)

    print("Генерация стандартных страниц...")
    print("Генерация статей...")
    for a in ARTICLES:
        p, c = render_article(a)
        write(p, c)

    for renderer in (render_otzyvy, render_akcii, render_garantii, render_voprosy, render_geografiya, render_stati, render_karta, render_404):
        p, c = renderer()
        write(p, c)

    # sitemap.xml
    today = date.today().isoformat()
    urls = "".join(
        f"<url><loc>{url(p)}</loc><lastmod>{today}</lastmod></url>" for p in all_paths if p != "404.html"
    )
    sitemap = f'<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">{urls}</urlset>'
    with open(os.path.join(OUT, "sitemap.xml"), "w", encoding="utf-8") as f:
        f.write(sitemap)
    print_done("sitemap.xml")

    # robots.txt (Clean-param — для Яндекса: адреса с метками UTM и т.п. не считать дублями)
    robots = (
        "User-agent: *\nAllow: /\nDisallow: /404\n\n"
        "User-agent: Yandex\nAllow: /\nDisallow: /404\n"
        "Clean-param: utm_source&utm_medium&utm_campaign&utm_content&utm_term&yclid&gclid&fbclid&_openstat&from\n\n"
        f"Sitemap: {url('sitemap.xml')}\n"
    )
    with open(os.path.join(OUT, "robots.txt"), "w", encoding="utf-8") as f:
        f.write(robots)
    print_done("robots.txt")

    write_web_assets()

    print(f"\nГотово! Сгенерировано страниц: {len(all_paths)}")


def write_web_assets():
    """Картинка для соцсетей (Open Graph), иконки и Web App Manifest."""
    og = os.path.join(OUT, "assets/img/og-image.jpg")
    if not os.path.exists(og):
        im = Image.open(os.path.join(OUT, "assets/img/vyezdnaya-himchistka-mebeli-kaliningrad.jpg")).convert("RGB")
        w, h = im.size
        ch = round(w * 630 / 1200)
        im = im.crop((0, (h - ch) // 2, w, (h - ch) // 2 + ch)).resize((1200, 630), Image.LANCZOS)
        im.save(og, "JPEG", quality=82, progressive=True)
        print_done("assets/img/og-image.jpg")
    for size in (192, 512):
        out = os.path.join(OUT, f"icon-{size}.png")
        if not os.path.exists(out):
            Image.open(os.path.join(OUT, "apple-touch-icon.png")).convert("RGB").resize((size, size), Image.LANCZOS).save(out, "PNG")
            print_done(f"icon-{size}.png")
    manifest = {
        "name": SITE["name"],
        "short_name": SITE["short_name"],
        "description": SITE["tagline"],
        "lang": "ru",
        "start_url": "./",
        "scope": "./",
        "display": "standalone",
        "background_color": "#ffffff",
        "theme_color": "#1868c1",
        "icons": [
            {"src": "icon-192.png", "sizes": "192x192", "type": "image/png"},
            {"src": "icon-512.png", "sizes": "512x512", "type": "image/png"},
            {"src": "favicon.svg", "sizes": "any", "type": "image/svg+xml"},
        ],
    }
    with open(os.path.join(OUT, "site.webmanifest"), "w", encoding="utf-8") as f:
        json.dump(manifest, f, ensure_ascii=False, indent=2)
    print_done("site.webmanifest")

if __name__ == "__main__":
    main()
